/**
 * Cambridge Vocabulary for IELTS Advanced — one VocabDeck per unit.
 * Generated by `src/scripts/build-cambridge-book.mjs` from wordlists + translations.
 */
import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const DATA_PATH = path.join(__dirname, "../data/vocab/cambridge-unit-vocab-decks.json")

/** @type {import("../models/VocabDeck.js").VocabDeck[]} */
export const CAMBRIDGE_UNIT_VOCAB_DECKS = JSON.parse(fs.readFileSync(DATA_PATH, "utf8"))
